t.script:
document.addEventListener('click', function(e) {
    var btn = e.target.closest('#add_to_cart, .js_check_product a.a-submit, .js_add_cart, [action*="/shop/cart/update"] .a-submit');
    if (btn) {
        var container = btn.closest('form') || btn.closest('.oe_product_cart') || btn.closest('.js_product') || document;

        // Try to get values from data- attributes on the button first
        var productName = btn.getAttribute('data-product-name');
        var productId = btn.getAttribute('data-product-id');
        var price = btn.getAttribute('data-product-price');
        var sku = btn.getAttribute('data-product-sku') || '';
        var imageUrl = btn.getAttribute('data-product-img') || '';
        var productUrl = btn.getAttribute('data-product-url') || window.location.href;

        // Fallbacks from DOM scraping
        if (!productId) {
            var productIdInput = container.querySelector('input[name="product_id"]');
            productId = productIdInput ? productIdInput.value : null;
        }
        if (!productName) {
            var nameElement = document.querySelector('h1') || container.querySelector('.o_wsale_products_item_title a') || container.querySelector('.product_name');
            productName = nameElement ? nameElement.textContent.trim() : 'Product';
        }
        if (!price) {
            var priceElement = container.querySelector('.oe_price .oe_currency_value') || container.querySelector('.product_price .oe_currency_value');
            price = priceElement ? priceElement.textContent : '0';
        }
        if (!imageUrl) {
            var imgElement = container.querySelector('img.product_detail_img') || container.querySelector('img.o_wsale_product_grid_img') || container.querySelector('img');
            imageUrl = imgElement ? imgElement.src : '';
        }
        if (!productUrl) {
            var urlLink = container.querySelector('.o_wsale_products_item_title a') || container.querySelector('a[itemprop="url"]');
            if (urlLink) {
                productUrl = urlLink.href;
            }
        }

        productId = productId ? parseInt(productId, 10) : null;
        price = price ? parseFloat(price.toString().replace(/[^0-9.]/g, '')) : 0.0;
        var qtyInput = container.querySelector('input[name="add_qty"]');
        var qty = qtyInput ? parseInt(qtyInput.value, 10) : 1;

        if (productId) {
            console.log("Klaviyo: Added to Cart event pushed (Global)", productName, productId, price, qty, productUrl, imageUrl);
            window._learnq = window._learnq || [];
            window._learnq.push(["track", "Added to Cart", {
                "AddedItemProductName": productName,
                "AddedItemProductID": productId,
                "AddedItemSKU": sku,
                "AddedItemPrice": price,
                "AddedItemQuantity": qty,
                "AddedItemURL": productUrl,
                "AddedItemImageURL": imageUrl,
                "ItemNames": [productName],
                "Items": [{
                    "ProductID": productId,
                    "SKU": sku,
                    "ProductName": productName,
                    "Quantity": qty,
                    "ItemPrice": price,
                    "RowTotal": price * qty,
                    "ProductURL": productUrl,
                    "ImageURL": imageUrl
                }]
            }]);
        }
    }
}, true);
